from pathlib import Path
import pandas as pd
r=Path(__file__).resolve().parents[1];s=pd.read_csv(r/"phase16/summary.csv");o=pd.read_csv(r/"phase20/summary.csv");style="<style>body{max-width:1100px;margin:40px auto;padding:0 20px;font:16px/1.7 system-ui;color:#234}table{border-collapse:collapse;font-size:13px}td,th{padding:7px;border-bottom:1px solid #ddd;text-align:right}.notice{background:#fff1df;padding:18px}</style>"
def table(d):return d.to_html(index=False,float_format=lambda x:f"{x:.6f}",border=0)
body="""<p class=notice>本页是源控制器人群上的机制探索。所有单步试验每次都从源参数重启，未来四窗暂停更新。因此它评估新写入的潜在价值，不是连续适应性能，也不是长期保留收益。</p><p>2种来源分类头，4位源控制器人员（7、17、27、37），每人64个均匀时间点，2种目标×4档步长，共4096条单步结果。仅写编码器既有LayerNorm仿射参数10960个；全局梯度裁剪1，逐张量投影半径0.1×max(源RMS,1)×sqrt(参数个数)。冻结分词器的最近码本查找不改变内部统计。</p><p>分类标签只用于离线未来CE及梯度诊断；不进入熵或掩码更新目标。掩码实现保留下游编码器CLS位置规则，无掩码输出与官方下游路径逐值一致；这是明确的适配辅助目标，非官方预训练完整复现。</p><h2>新写入收益</h2><p>收益单位为未来四窗平均交叉熵下降（nats）。先逐人平均再对四人等权。beneficial/harmful 的阈值为±1e−6；oracle是事后知道标签时选择KEEP/WRITE的上界，不是可部署策略。窗口不是独立受试者。</p>"""+table(s)+"""<p>适中步长熵更新有正的平均单步收益，但大步长少数严重损害能抵消多数小收益。掩码目标与未来任务梯度平均对齐很弱。真正连续运行的源验证结果见下一阶段，不能用此处单步收益替代。</p><h2>仅凭当前信号能否识别有益写入？</h2><p>以下是步长0.01的四人留一验证：三人训练Ridge，另一人评分。输入只含当前预测熵／置信度、辅助损失、梯度范数、当前概率、当前与前一窗频谱距离及当前52维频谱特征。未来梯度余弦、真实类别、未来损失等标签衍生量均不进入输入。confidence同样接受未来收益监督，只是特征消融。</p>"""+table(o[o.lr==.01])+"""<p>加入信号或频谱的学习器未稳定超过直接WRITE或简单熵阈值；掩码写入的学习筛选也未在此小样本源人群上形成正收益。这限制了当前可观察信号和学习器的证据力度，不能证明所有策略均不可学。</p><p><a href=protocol.json>单步协议</a> · <a href=../phase20/protocol.json>可观察性协议</a> · <a href=../phase17/report.html>完整源验证连续更新</a> · <a href=../research_overview.html>总览</a></p>"""
(r/"phase16/report.html").write_text("<!doctype html><html lang=zh><meta charset=utf-8><title>新写入价值与可观察性</title>"+style+"<body><h1>新写入价值与可观察性</h1>"+body+"</body></html>")
print("Mechanism report written")
